#!/usr/bin/env bash
# Build the supervisor module executable: ardupilot/modules/supervisor/build.sh
#
# The same steps and outputs as ardupilot/build.sh (records from Lean, compile, code hash over every
# file the compiler read, link to build/modules/supervisor/supervisor), with what that script does
# not do for one module:
#   * the feature switches of probe/features.txt are appended to flags.txt's flags;
#   * the compiled set is sources.txt (ArduPilot, read only) + adapter.cpp + stand_ins/*.cpp
#     (hand-written) + gen/out/*.cpp (generated by gen/run.sh from the real headers and .cpp files;
#     the real files the generator copies from are added to the code hash);
#   * up to 4 compiles in parallel, an object is rebuilt only if a file it read changed;
#   * the flags go through a response file (the command line is long).
set -euo pipefail

NAME=supervisor
HERE="$(cd "$(dirname "$0")" && pwd)"
HARNESS="$(cd "$HERE/../../.." && pwd)"
ARDUPILOT_ROOT="${ARDUPILOT_ROOT:-$HARNESS/deps/ardupilot}"
ARDUPILOT_ROOT="$(cd "$ARDUPILOT_ROOT" && pwd -P)"
CXX="${CXX:-clang++}"
OUT="$HARNESS/build/modules/$NAME"
GEN="$HARNESS/build/gen/$NAME"
HARNESS_BIN="$HARNESS/.lake/build/bin/harness"
[ -x "$HARNESS_BIN" ] || { echo "build.sh: $HARNESS_BIN missing; run 'lake build' first" >&2; exit 1; }
mkdir -p "$OUT/obj" "$OUT/cfg" "$OUT/log" "$GEN"

# 1. records
(cd "$HARNESS" && "$HARNESS_BIN" gen "$NAME" > /dev/null)
# (harness gen rewrites the header; keep its old time stamp when its text did not change)
# the parameter record's fields by name, for the adapter (AP_Param is set by name)
python3 -I - "$GEN/module_records.h" > "$GEN/param_table.inc" <<'PY'
import re, sys
txt = open(sys.argv[1]).read()
body = re.search(r'struct Params \{(.*?)\};', txt, re.S).group(1)
print('// written by ardupilot/modules/supervisor/build.sh from module_records.h')
for ty, name in re.findall(r'^\s*(\w+)\s+(\w+);', body, re.M):
    kind = {'float': 'f', 'uint32_t': 'u', 'int32_t': 'i', 'bool': 'b'}[ty]
    print('    {"%s", offsetof(Params, %s), \'%s\'},' % (name, name, kind))
PY
# the f32 output fields, for the poison trap's scan (adapter.cpp)
python3 -I - "$GEN/module_records.h" > "$GEN/output_f32.inc" <<'PY'
import re, sys
txt = open(sys.argv[1]).read()
body = re.search(r'struct Output \{(.*?)\};', txt, re.S).group(1)
print('// written by ardupilot/modules/supervisor/build.sh from module_records.h')
for ty, name in re.findall(r'^\s*(\w+)\s+(\w+);', body, re.M):
    if ty == 'float':
        print('    {"%s", offsetof(Output, %s)},' % (name, name))
PY

# 2. configuration headers as ardupilot/build.sh writes them
cat > "$OUT/cfg/ap_config.h.new" <<'EOF'
// written by ardupilot/modules/supervisor/build.sh: the host checks waf's configure writes for the SITL board
#pragma once
#define HAVE_CMATH_ISFINITE 1
#define HAVE_CMATH_ISINF 1
#define HAVE_CMATH_ISNAN 1
#define NEED_CMATH_ISFINITE_STD_NAMESPACE 1
#define NEED_CMATH_ISINF_STD_NAMESPACE 1
#define NEED_CMATH_ISNAN_STD_NAMESPACE 1
EOF
{
  echo "// written by ardupilot/modules/supervisor/build.sh from libraries/AP_HAL_SITL/hwdef/sitl/hwdef.dat"
  echo "#pragma once"
  sed -n 's/^define \(.*\)$/#define \1/p' "$ARDUPILOT_ROOT/libraries/AP_HAL_SITL/hwdef/sitl/hwdef.dat"
} > "$OUT/cfg/hwdef.h.new"
# replace only if changed, so that unchanged objects are not rebuilt
for f in ap_config.h hwdef.h; do
  cmp -s "$OUT/cfg/$f.new" "$OUT/cfg/$f" && rm "$OUT/cfg/$f.new" || mv "$OUT/cfg/$f.new" "$OUT/cfg/$f"
done

FLAGS=(-std=gnu++11 -O2 -ffp-contract=off -fno-fast-math -ftrapping-math
       -cl-single-precision-constant -fsigned-char -fno-exceptions -fno-builtin
       -ffunction-sections -fdata-sections -Wno-gnu-designator -Wno-invalid-offsetof
       -DARDUPILOT_BUILD "-D__AP_LINE__=__LINE__"
       -DCONFIG_HAL_BOARD=HAL_BOARD_SITL -DCONFIG_HAL_BOARD_SUBTYPE=HAL_BOARD_SUBTYPE_NONE
       -DAP_NETWORKING_ENABLED=0
       -include ap_config.h)
while IFS= read -r line; do
  line="${line%%#*}"
  line="$(echo "$line" | tr -d '[:space:]')"
  [ -n "$line" ] && FLAGS+=("$line")
done < "$HERE/flags.txt"
# the feature switches (probe/features.txt, -DNAME=V lines) as a forced-include header rather than
# ~470 command-line flags, so that the manifest's flags string stays short (module_protocol.h's
# describe buffer is 16 kB); the header is read by the compiler, so it is in the code hash
{
  echo "// written by ardupilot/modules/supervisor/build.sh from ardupilot/modules/supervisor/probe/features.txt"
  echo "#pragma once"
  sed -n 's/^-D\([A-Za-z0-9_]*\)=\(.*\)$/#define \1 \2/p' "$HERE/probe/features.txt"
} > "$OUT/cfg/supervisor_features.h.new"
cmp -s "$OUT/cfg/supervisor_features.h.new" "$OUT/cfg/supervisor_features.h" &&
  rm "$OUT/cfg/supervisor_features.h.new" ||
  mv "$OUT/cfg/supervisor_features.h.new" "$OUT/cfg/supervisor_features.h"
FLAGS+=(-include supervisor_features.h)
INCLUDES=(-I"$OUT/cfg" -I"$GEN" -I"$HARNESS/cpp" -I"$HERE/stand_ins" -I"$HERE/gen/out"
          -I"$ARDUPILOT_ROOT/libraries" -I"$ARDUPILOT_ROOT/libraries/AP_Common/missing"
          -I"$ARDUPILOT_ROOT/ArduCopter" -I"$HARNESS/build/gen/mavlink")
# as waf links on darwin for clang >= 15 (Tools/ardupilotwaf/boards.py:593-597): the classic
# linker accepts the packed AP_FWVersion structure's unaligned pointers
LINK_FLAGS=(-Wl,-dead_strip,-ld_classic)
printf '%s\n' "${FLAGS[@]}" "${INCLUDES[@]}" -w > "$OUT/flags.rsp"
# the generated stand-ins, from the real headers under these flags (files rewritten only if changed)
RSP="$OUT/flags.rsp" "$HERE/gen/run.sh" > "$OUT/gen.log"

SOURCES=()
while IFS= read -r line; do
  line="${line%%#*}"
  line="$(echo "$line" | tr -d '[:space:]')"
  [ -n "$line" ] && SOURCES+=("$ARDUPILOT_ROOT/$line")
done < "$HERE/sources.txt"
for f in "$HERE"/stand_ins/*.cpp "$HERE"/gen/out/*.cpp; do SOURCES+=("$f"); done
# the adapter last: its static constructor (a re-executed init, adapter.cpp) must run after every
# other one, and Mach-O runs them in link order
SOURCES+=("$HERE/adapter.cpp")

# object name: <dir>_<file>.o; rebuilt if missing, or older than any file its .d lists, or if
# the response file changed
objname() { echo "$OUT/obj/$(basename "$(dirname "$1")")_$(basename "$1" .cpp)"; }
RSP_SUM="$(shasum -a 256 "$OUT/flags.rsp" | cut -d' ' -f1)"
[ -f "$OUT/flags.sum" ] && [ "$(cat "$OUT/flags.sum")" = "$RSP_SUM" ] || rm -f "$OUT"/obj/*.o
echo "$RSP_SUM" > "$OUT/flags.sum"
TODO=()
for src in "${SOURCES[@]}"; do
  o="$(objname "$src")"
  if [ ! -f "$o.o" ] || [ ! -f "$o.d" ]; then TODO+=("$src"); continue; fi
  stale=0
  for dep in $(sed -e 's/\\$//' -e 's/^[^:]*: *//' "$o.d"); do
    [ "$dep" -nt "$o.o" ] && { stale=1; break; }
  done
  [ $stale = 1 ] && TODO+=("$src")
done
echo "compiling ${#TODO[@]} of ${#SOURCES[@]} sources"
export OUT CXX
compile_one() {
  src="$1"; o="$OUT/obj/$(basename "$(dirname "$src")")_$(basename "$src" .cpp)"
  if (cd "$OUT/obj" && "$CXX" @"$OUT/flags.rsp" -MD -MF "$o.d" -c "$src" -o "$o.o") > "$o.log" 2>&1
  then echo "ok   $src"; else rm -f "$o.o"; echo "FAIL $src"; fi
}
export -f compile_one
if [ ${#TODO[@]} -gt 0 ]; then
  printf '%s\n' "${TODO[@]}" | xargs -n1 -P4 bash -c 'compile_one "$0"' > "$OUT/compile_status.txt"
  if grep -q '^FAIL' "$OUT/compile_status.txt"; then
    grep '^FAIL' "$OUT/compile_status.txt"
    echo "build.sh: compile errors; see $OUT/obj/*.log" >&2
    exit 1
  fi
fi

# 3. code hash: every file the compiler read, plus the real files gen/ copied text from
label() {
  local p="$1"
  case "$p" in
    "$ARDUPILOT_ROOT"/*) echo "\$ARDUPILOT_ROOT/${p#"$ARDUPILOT_ROOT"/}" ;;
    "$HARNESS"/*) echo "\$HARNESS/${p#"$HARNESS"/}" ;;
    *) echo "$p" ;;
  esac
}
DEPS="$OUT/deps.txt"
{
  cat "$OUT"/obj/*.d | sed -e 's/\\$//' -e 's/^[^:]*: *//' | tr ' ' '\n' | sed '/^$/d'
  grep -h "^// Stage: .*copied from" "$HERE"/gen/out/*.cpp |
    sed 's/.*\$ARDUPILOT_ROOT\/\([^;]*\);.*/\1/' | sed "s|^|$ARDUPILOT_ROOT/|"
  ls "$HERE"/gen/*.py "$HERE"/gen/run.sh "$HERE"/probe/features.txt "$HERE"/flags.txt "$HERE"/sources.txt
} | sort -u | while IFS= read -r f; do realpath "$f"; done | sort -u > "$DEPS"
COMPILER="$("$CXX" --version | head -1)"
{
  while IFS= read -r f; do
    printf '%s  %s\n' "$(shasum -a 256 "$f" | cut -d' ' -f1)" "$(label "$f")"
  done < "$DEPS" | LC_ALL=C sort -k2
  echo "flags: ${FLAGS[*]}"
  echo "link: ${LINK_FLAGS[*]}"
  echo "compiler: $COMPILER"
} > "$OUT/code_inputs.txt"
CODE_HASH="$(shasum -a 256 "$OUT/code_inputs.txt" | cut -d' ' -f1)"
printf 'ARDUPILOT_ROOT=%s\nHARNESS=%s\n' "$ARDUPILOT_ROOT" "$HARNESS" > "$OUT/roots.env"
FLAGS_ESC="$(printf '%s ' "${FLAGS[@]}" | sed 's/\\/\\\\/g; s/"/\\"/g')"
cat > "$OUT/codehash.cpp" <<EOF
// written by ardupilot/modules/supervisor/build.sh; not part of the code hash (it holds it)
extern const char harness_code_hash[] = "$CODE_HASH";
extern const char harness_build_flags[] = "$FLAGS_ESC";
extern const char harness_compiler[] = "$COMPILER";
EOF
"$CXX" -c "$OUT/codehash.cpp" -o "$OUT/codehash.o"

# 4. link
OBJS=()
for src in "${SOURCES[@]}"; do OBJS+=("$(objname "$src").o"); done
"$CXX" "${LINK_FLAGS[@]}" "${OBJS[@]}" "$OUT/codehash.o" -o "$OUT/$NAME" 2> "$OUT/link.log" || {
  grep -c "Undefined symbols\|^  \"" "$OUT/link.log" | sed 's/^/undefined: /' >&2
  echo "build.sh: link failed; see $OUT/link.log" >&2; exit 1; }
echo "built $OUT/$NAME"
echo "  sources: ${#SOURCES[@]} compiled, $(wc -l < "$DEPS" | tr -d ' ') files in the code hash"
echo "  code hash: $CODE_HASH"
